  Skills: '#E8A6C4',
  Messages: '#DE8E62',
}

const DARK: CtxPalette = {
  category: PASTEL,
  fallback: ['#C8C8C8', '#9CD3B0', '#D9B38C'],
  track: '#3A3E47',
  mark: '#F28B9B',
  chipInk: '#1E2127',
  dim: '#8A909B',
  bright: '#E8EAED',
  warn: '#F0C987',
  danger: '#F28B9B',
  agentAccent: '#C3B1F5',
  agentDone: '#A8C98A',
}

const THEME: CtxPalette = {
  category: {
    Messages: 'claude',
    'System tools': 'suggestion',
    Skills: 'warning',
    'Memory files': 'remember',
    'System prompt': 'inactive',
    'MCP tools': 'permission',
    'Custom agents': 'success',
    'MCP server instructions': 'planMode',
  },
  fallback: ['subtle'],
  track: 'inactive',
  mark: 'error',
  chipInk: 'inverseText',
  dim: 'subtle',
  bright: 'text',
  warn: 'warning',
  danger: 'error',
  agentAccent: 'claude',
  agentDone: 'success',
}

// 원본 statusline-ctx.py의 PASTEL/TRACK/MARK/CHIP_INK/DIM/BRIGHT/WARN/DANGER 그대로.
const GRAY: CtxPalette = {
  category: PASTEL,
  fallback: ['#C8C8C8', '#9CD3B0', '#D9B38C'],
  track: '#AEB0BA',
  mark: '#9F1239',
  chipInk: '#1F232E',
